          "content": "Tổ tiên của triều đại nhà Chu là Cổ công Đàm Phụ, cũng chính là Chu Thái Vương. Vị vua này có ba người con trai là Thái Bá, Trọng Ung và Quý Lịch. Thái Bá là con trưởng, tính cách khiêm nhường. Chu Thái Vương còn có cháu trai là Cơ Xương (sau này là Chu Văn Vương)."
