          "type": "text",
          "content": "Công Sơn Phất Nhiễu vốn là một bề tôi dưới trướng của Quý Hoàn tử, đại phu nước Lỗ. Công Sơn là họ, Phất Nhiễu là tên, sau này Phất Nhiễu chiếm cứ được huyện Thành Phí, liền quay ra phản bội Quý Hoàn. Công Sơn Phất Nhiễu từ lâu đã biết tiếng tăm lẫy lừng của Khổng Tử nên cho người đi mời ông."
