          "content": "Quý Khang Tử là thứ tử của Quý Hoàn Tử. Khi Lỗ Ai Công lên ngôi, ông ta nắm quyền và khống chế cả về quân sự và chính trị của nước Lỗ. Quý Khang Tử thường mời Khổng Tử đến thỉnh giáo những kinh nghiệm về trị quốc."
