          "type": "text",
          "content": "Tử Cống trả lời: \"Văn Vương, Vũ Vương thống nhất thiên hạ, Chu Công Điện định ra chính trị và văn hóa Tây Chu, văn hóa nhà Chu lưu truyền mãi sau này mặc dù có sự đổi thay thời đại."
