          "content": "- Ví dụ như Lão Tử quan chép sử nhà Chu, Cừ Bá Ngọc đại thần nước Vệ, Yến Bình Trọng đại phu nước Tề, Tử Sản đại phu nước Trịnh, Mạnh Công Trác đại phu nước Lỗ, còn có Lão Thái Tử nước Sở nữa, v.v... Ngoài ra, thầy tôi còn ca ngợi Giới Tử Thôi đại phu nước Lỗ và Liễu Hạ Huệ."
