          "type": "text",
          "content": "Vì sao Khổng Tử lại nói câu này? Vốn là, trong số học trò của Khổng Tử có cả người nghèo và người giàu, vừa có con em các quan lại vừa có con em của dân nghèo; có cả người miền Nam và miền Bắc; có cả người già, cả người trẻ. Khổng Tử coi tất cả học sinh đều như nhau, chưa bao giờ nhìn họ với con mắt khác nhau."
