          "type": "text",
          "content": "Một ẩn sĩ danh tiếng đến gặp Lỗ Ai Công. Vua Lỗ nói với ẩn sĩ rằng: \"Đất này có rất nhiều nho sĩ, nhưng có rất ít người học tập đạo thuật\"."
