          "content": "Ẩn sĩ đáp: \"Tôi nghe nói, nhà nho đội mũ tròn biết thiên thời; đi giày vuông biết địa lợi; dùng dải lụa ngũ sắc gói viên ngọc, khi lâm sự rất quyết đoán. Người quân tử phải hiểu đạo thuật này, vị tất phải mặc quần áo gì. Mặc bộ quần áo này chắc gì đã hiểu được đạo thuật. Ngài đã biết vậy sao không hạ chỉ cho nước Lỗ rằng: \"Nếu không hiểu đạo mà lại mặc bộ quần áo nho sĩ thì sẽ bị xử tội chết.\""
