          "content": "Lỗ Ai Công nghe theo, ra chỉ dụ. Chỉ trong năm ngày, ngoài một người có tuổi mặc quần áo nho gia đứng ngoài cửa, trên toàn nước Lỗ chẳng có ai dám mặc quần áo nho gia nữa. Lỗ Ai Công cho triệu người mặc quần áo nho gia vào triều, hỏi han chuyện quốc gia đại sự trong thiên hạ, quả nhiên người này nói trôi chảy mọi sự."
